TLM.f("Sancti/05-12",{"officium":"Ss. Nerei, Achillei et Domitillæ Virginis atque Pancratii Martyrum","rule":["Evangelium non appropriatum","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 32:18; 32:19; 32:20"},{"k":"text","la":"Ecce, óculi Dómini super timéntes eum, sperántes in misericórdia ejus, allelúja: ut erípiat a morte ánimas eórum: quóniam adjútor et protéctor noster est, allelúja, allelúja."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce, óculi Dómini super timéntes eum, sperántes in misericórdia ejus, allelúja: ut erípiat a morte ánimas eórum: quóniam adjútor et protéctor noster est, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Semper nos, Dómine, Mártyrum tuórum Nérei, Achíllei, Domitíllæ atque Pancrátii fóveat, quǽsumus, beáta solémnitas: et tuo dignos reddat obséquio."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, pœniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 4:46-53"},{"k":"text","la":"In illo témpore: Erat quidam régulus, cujus fílius infirmabátur Caphárnaum. Hic cum audísset, quia Jesus adveníret a Judǽa in Galilǽam, ábiit ad eum, et rogábat eum, ut descénderet et sanáret fílium ejus: incipiébat enim mori. Dixit ergo Jesus ad eum: Nisi signa et prodígia vidéritis, non créditis. Dicit ad eum régulus: Dómine, descénde, priúsquam moriátur fílius meus. Dicit ei Jesus: Vade, fílius tuus vivit. Crédidit homo sermóni, quem dixit ei Jesus, et ibat. Jam autem eo descendénte, servi occurrérunt ei et nuntiavérunt, dicéntes, quia fílius ejus víveret. Interrogábat ergo horam ab eis, in qua mélius habúerit. Et dixérunt ei: Quia heri hora séptima relíquit eum febris. Cognóvit ergo pater, quia illa hora erat, in qua dixit ei Jesus: Fílius tuus vivit: et crédidit ipse et domus ejus tota."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum(, allelúja, allelúja)."}],"Secreta":[{"k":"text","la":"Sanctórum Martyrum tuórum, quǽsumus. Dómine, Nérei, Achíllei, Domitíllæ atque Pancrátii sit tibi grata conféssio: quæ et múnera nostra comméndet, et tuam nobis indulgéntiam semper implóret."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Gaudéte, justi, in Dómino, allelúja: rectos decet collaudátio, allelúja."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine: ut beatórum Mártyrum tuórum Nérei, Achíllei, Domitíllæ atque Pancrátii deprecatiónibus, sacraménta sancta, quæ súmpsimus, ad tuæ nobis profíciant placatiónis augméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"849e490f5758e74b":{"t":"Ps 32, 18 i 19 i 20, Ps 32, 1\n(Ps 32, 18 i 19 i 20) Gle, oči Gospodnje gledaju one koji ga se boje, one koji se uzdaju u milosrđe njegovo, <i>aleluja</i>.\nOn izbavlja njihov život od smrti. On je naš pomoćnik i zaštitnik, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 32 1) Radujte se, pravednici, u Gospodinu, pravednima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 32, 18 i 19 i 20) Gle, oči Gospodnje gledaju one koji ga se boje, one koji se uzdaju u milosrđe njegovo, <i>aleluja</i>.\nOn izbavlja njihov život od smrti. On je naš pomoćnik i zaštitnik, <i>aleluja</i>, <i>aleluja</i>."},"e62ee888c88232b7":{"t":"<i>Pomolimo se</i>.\nNeka nas uvijek potpomaže, molimo, Gospodine, blažena svetkovina mučenika tvojih Nereja, Ahileja, Domitile i Pankracija i učini dostojnima tvoje službe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c600ca35b26cf613":{"t":"Mudr 5, 1-5\nČitanje knjige Mudrosti. Pravednici će se junački održati protiv onih koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smest će se od užasnog straha i čudit će se neočekivanom njihovu spasu. Mislit će u sebi očajni i jecajući od duševne boli: To su oni kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima."},"91f190df4dbe29b5":{"t":"<i>Aleluja</i>, <i>aleluja</i>.\nOvo je pravo bratstvo koje je pobijedilo opačine svijeta, slijedilo je Krista i zadobilo slavno nebesko kraljevstvo. <i>Aleluja</i>.\nTebe. Gospodine, hvali mučenika svijetla vojska. <i>Aleluja</i>."},"2cb888720d7cc4b1":{"t":"Iv 4, 46-53\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bolovao je u Kafarnaumu sin nekoga kraljevskog činovnika. Kad je ovaj čuo, da je Isus došao iz Judeje u Galileju, pođe k njemu i zamoli ga da dođe i da mu ozdravi sina koji bijaše na umoru. Isus mu reče: Ako ne vidite znakova i čudesa, ne vjerujete. Kraljevski činovnik ponovi: Gospodine, dođi prije nego umre moj sin! Isus mu reče: Pođi! tvoj sin živi. Čovjek povjerova Isusovoj riječi i pođe. Kad se on vraćao kući dođu mu u susret sluge koji mu jave: Sin je tvoj ozdravio. On ih upita za vrijeme, kad mu je bilo bolje. Sluge mu odgovore: Jučer oko sedam sati pusti ga groznica. Tad otac upozna, da je to bilo u onaj sat kad mu Isus reče: Tvoj sin živi. I povjerova on i sav njegov dom."},"f6559b160ccd64cf":{"t":"Ps 88, 6\nNebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>, <i>aleluja</i>."},"e1874c46ab8b71f6":{"t":"Bilo ti milo, molimo Gospodine, priznavanje svetih mučenika tvojih Nereja, Ahileja, Domitile i Pankracija. da preporuči naše darove i uvijek nam isprosi tvoje oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"aa30249bc0fea185":{"t":"Ps 32, 1\nRadujte se, pravednici u Gospodinu, <i>aleluja</i>,\npravednima dolikuje da ga hvale, <i>aleluja</i>."},"f9cb46e6b06deb17":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nam po molitvama blaženih mučenika tvojih Nereja, Ahileja, Domitile i Pankracija sveta otajstva koja smo primili povećaju pomirenje s tobom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"}}});
